  ('my-boss-wronged-me', 'اتق دعوة المظلوم فإنه ليس بينها وبين الله حجاب', '2026-08-21T12:00:00Z', $j$[{"id": "ZSajjm4z", "text": "أنَّ النَّبيَّ صلَّى اللهُ عليه وسلَّم بَعَثَ مُعاذًا إلى اليَمَنِ، فقال: اتَّقِ دَعوةَ المَظلومِ؛ فإنَّها ليس بينَها وبينَ اللهِ حِجابٌ.", "rawi": "عبدالله بن عباس", "book": "صحيح البخاري", "ref": "2448", "grade": "[صحيح]", "takhrij": "أخرجه مسلم (19) مطولاً باختلاف يسير", "categories": [{"id": "8c29416e2e4192d0d00fc419af5025f3", "name": "آداب الدعاء - استجابة الدعاء"}, {"id": "7d8a5c379add28bff2bdd316180367bd", "name": "آداب الدعاء - من يستجاب دعاؤهم"}, {"id": "e24688b268fbd808d34876ef83219b36", "name": "سرايا - تأمير الأمراء على البعوث والسرايا ووصيتهم"}, {"id": "66bfdd62a6e70b15dfb492dec2d0182c", "name": "مظالم - تحريم الظلم"}, {"id": "7cc240fbf85a1effd1ef5bf9071a6721", "name": "مظالم - دعوة المظلوم"}]}]$j$::jsonb,
