  ('i-cannot-stop-being-angry', 'ليس الشديد بالصرعة إنما الشديد الذي يملك نفسه عند الغضب', '2026-08-21T12:00:00Z', $j$[{"id": "SllC88XC", "text": "ليس الشَّديدُ بالصُّرَعةِ، إنَّما الشَّديدُ الذي يَملِكُ نَفسَه عِندَ الغَضَبِ.", "rawi": "أبو هريرة", "book": "صحيح البخاري", "ref": "6114", "grade": "[صحيح]", "takhrij": "أخرجه البخاري (6114)، ومسلم (2609)", "categories": [{"id": "f7087a4821eeeafbe75d852c9a7f2468", "name": "رقائق وزهد - الحلم"}, {"id": "48c7a2bd02e7f84713aa613da78116d4", "name": "رقائق وزهد - جهاد النفس"}, {"id": "c1a304d349b9f3f9dda9ca22d8032bea", "name": "رقائق وزهد - ما جاء في ترك الغضب"}, {"id": "f3d5a8b16c", "name": "آداب عامة - الأخلاق الحميدة الحسنة"}, {"id": "f5dda7705e", "name": "رقائق وزهد - المجاهدة"}]}]$j$::jsonb,
