  ('my-parents-ask-too-much', 'من أحق الناس بحسن صحابتي', '2026-08-21T12:00:00Z', $j$[{"id": "Y0ncQmYf", "text": "جاءَ رَجُلٌ إلى رَسولِ اللهِ صلَّى اللهُ عليه وسلَّم، فقال: مَن أحَقُّ النَّاسِ بحُسنِ صَحابَتي؟ قال: أُمُّكَ، قال: ثُمَّ مَن؟ قال: ثُمَّ أُمُّكَ، قال: ثُمَّ مَن؟ قال: ثُمَّ أُمُّكَ، قال: ثُمَّ مَن؟ قال: ثُمَّ أبوكَ. وفي حَديثِ قُتَيبةَ: مَن أحَقُّ بحُسنِ صَحابَتي؟ ولم يَذكُرِ النَّاسَ.", "rawi": "أبو هريرة", "book": "صحيح مسلم", "ref": "2548", "grade": "[صحيح]", "takhrij": "أخرجه البخاري (5971)، ومسلم (2548).", "categories": [{"id": "22a7e02c5ec9f4b9dd868b074d914d95", "name": "بر وصلة - عظم حق الأم"}, {"id": "2b2916337e", "name": "بر وصلة - التعاون على البر والتقوى"}, {"id": "de45c849aa", "name": "بر وصلة - بر الوالدين وحقهما"}]}]$j$::jsonb,
