  ('i-keep-putting-it-off', 'أحب الأعمال إلى الله أدومها وإن قل', '2026-08-21T12:00:00Z', $j$[{"id": "NpZLQ79z", "text": "أحَبُّ الأعمالِ إلى اللهِ تَعالى أدوَمُها وإن قَلَّ. قال: وكانَت عائِشةُ إذا عَمِلَتِ العَمَلَ لَزِمَتْه.", "rawi": "عائشة أم المؤمنين", "book": "صحيح مسلم", "ref": "783", "grade": "[صحيح]", "takhrij": "أخرجه البخاري (6465)، ومسلم (783).", "categories": [{"id": "f402326959424e033e54f400fe017d24", "name": "رقائق وزهد - أي الأعمال أفضل"}, {"id": "79ebfc9e5a40c080ba07e5ba675ce75c", "name": "رقائق وزهد - القصد والمداومة على العمل"}, {"id": "86f3241ea41ca0ecd2c030f93b85cf01", "name": "مناقب وفضائل - عائشة بنت أبي بكر الصديق"}, {"id": "253dacba9214a5f0f35dc00ac69b7cee", "name": "مناقب وفضائل - فضائل أصحاب النبي صلى الله عليه وسلم"}, {"id": "6d2a45e6bf", "name": "مناقب وفضائل - فضائل أزواج النبي صلى الله عليه وسلم"}]}]$j$::jsonb,
