  ('someone-spoke-badly-of-me', 'من كان يؤمن بالله واليوم الآخر فليقل خيرا أو ليصمت', '2026-08-21T12:00:00Z', $j$[{"id": "Mgy5kJET", "text": "مَن كان يُؤمِنُ باللهِ واليَومِ الآخِرِ فليُكرِمْ ضَيفَه، ومَن كان يُؤمِنُ باللهِ واليَومِ الآخِرِ فليَصِلْ رَحِمَه، ومَن كان يُؤمِنُ باللهِ واليَومِ الآخِرِ فليَقُلْ خَيرًا أو ليَصمُتْ.", "rawi": "أبو هريرة", "book": "صحيح البخاري", "ref": "6138", "grade": "[صحيح]", "takhrij": "أخرجه البخاري (6138)، ومسلم (47)", "categories": [{"id": "7645078936fef500aeb163e90bc9eadb", "name": "آداب الكلام - الصمت وقلة الكلام"}, {"id": "04e54b76f7db0aeac9a585e27c91d020", "name": "آداب المجلس - إكرام الضيف"}, {"id": "0a11b7432ebc1358348a305a4a982b28", "name": "إيمان - الأعمال التي من الإيمان"}, {"id": "5f2b08bf0571f17e6f6cc83e7c6f4ce3", "name": "بر وصلة - صلة الرحم وتحريم قطعها"}, {"id": "f3d5a8b16c", "name": "آداب عامة - الأخلاق الحميدة الحسنة"}]}]$j$::jsonb,
   'Mgy5kJET', 'أخرجه البخاري (6138)، ومسلم (47)', $j$[{"id": "7645078936fef500aeb163e90bc9eadb", "name": "آداب الكلام - الصمت وقلة الكلام"}, {"id": "04e54b76f7db0aeac9a585e27c91d020", "name": "آداب المجلس - إكرام الضيف"}, {"id": "0a11b7432ebc1358348a305a4a982b28", "name": "إيمان - الأعمال التي من الإيمان"}, {"id": "5f2b08bf0571f17e6f6cc83e7c6f4ce3", "name": "بر وصلة - صلة الرحم وتحريم قطعها"}, {"id": "f3d5a8b16c", "name": "آداب عامة - الأخلاق الحميدة الحسنة"}]$j$::jsonb),
  ('i-lost-someone', 'إن العين تدمع والقلب يحزن ولا نقول إلا ما يرضي ربنا', '2026-08-21T12:00:00Z', $j$[{"id": "dKKm2UCZ", "text": "دَخَلنا مع رَسولِ اللهِ صلَّى اللهُ عليه وسلَّم على أبي سَيفٍ القَينِ، وكان ظِئرًا لإبراهيمَ عليه السَّلامُ، فأخَذَ رَسولُ اللهِ صلَّى اللهُ عليه وسلَّم إبراهيمَ، فقَبَّلَه، وشَمَّه، ثُمَّ دَخَلنا عليه بَعدَ ذلك وإبراهيمُ يَجودُ بنَفسِه، فجَعَلَت عَينا رَسولِ اللهِ صلَّى اللهُ عليه وسلَّم تَذرِفانِ، فقال له عبدُ الرَّحمَنِ بنُ عَوفٍ رَضيَ اللهُ عنه: وأنتَ يا رَسولَ اللهِ؟ فقال: يا ابنَ عَوفٍ إنَّها رَحمةٌ، ثُمَّ أتبَعَها بأُخرى، فقال صلَّى اللهُ عليه وسلَّم: إنَّ العَينَ تَدمَعُ، والقَلبَ يَحزَنُ، ولا نَقولُ إلَّا ما يَرضى رَبُّنا، وإنَّا بفِراقِكَ يا إبراهيمُ لَمَحزونونَ.", "rawi": "أنس بن مالك", "book": "صحيح البخاري", "ref": "1303", "grade": "[صحيح]", "takhrij": "أخرجه البخاري (1303)، ومسلم (2315)", "categories": [{"id": "8b61cc8ce2086a05ed92a2943a90633f", "name": "جنائز وموت - البكاء على الميت"}, {"id": "e5e1d1495f4bde519317042bb036d595", "name": "رقائق وزهد - الحزن والبكاء"}, {"id": "fa344dd4bbf0ffb20f5ca6db5a6d8808", "name": "فضائل النبي وصفته ودلائل النبوة - رحمته"}, {"id": "4a9b4d17ea0f23e49dc1a032ac8c1114", "name": "مناقب وفضائل - إبراهيم بن النبي صلى الله عليه وسلم"}, {"id": "5c7577c95e", "name": "جنائز وموت - الحزن لموت الأفاضل"}]}]$j$::jsonb,
