  ('i-cannot-forgive-myself', 'لله أفرح بتوبة عبده', '2026-08-21T12:00:00Z', $j$[{"id": "hjugjsr9", "text": "قال اللهُ عزَّ وجلَّ: أنا عِندَ ظَنِّ عَبدي بي، وأنا معهُ حَيثُ يَذكُرُني، واللهِ لَلَّهُ أفرَحُ بتَوبةِ عَبدِه مِن أحَدِكُم يَجِدُ ضالَّتَه بالفَلاةِ، ومَن تَقَرَّبَ إلَيَّ شِبرًا تَقَرَّبتُ إليه ذِراعًا، ومَن تَقَرَّبَ إلَيَّ ذِراعًا تَقَرَّبتُ إليه باعًا، وإذا أقبَلَ إلَيَّ يَمشي أقبَلتُ إليه أُهَروِلُ.", "rawi": "أبو هريرة", "book": "صحيح مسلم", "ref": "2675", "grade": "[صحيح]", "takhrij": "أخرجه البخاري (7405)، ومسلم (2675).", "categories": [{"id": "8713a5272a209b603b25cfd07136d927", "name": "أدعية وأذكار - فضل الذكر"}, {"id": "02c7f559b5fde46cd9ac71b1ac1fcc3f", "name": "توبة - الحض على التوبة"}, {"id": "0746b33219956b3c38198e1f4c7fb528", "name": "رقائق وزهد - الاجتهاد في العبادة"}, {"id": "248c5bafb1755ee9929b5dda873011b3", "name": "رقائق وزهد - حسن الظن بالله"}, {"id": "3b314bd99d", "name": "إحسان - الحث على الأعمال الصالحة"}]}]$j$::jsonb,
