  ('i-am-far-from-home', 'كن في الدنيا كأنك غريب أو عابر سبيل', '2026-08-21T12:00:00Z', $j$[{"id": "scFZxN1c", "text": "أخَذَ رَسولُ اللهِ صلَّى اللهُ عليه وسلَّم بمَنكِبي، فقال: كُنْ في الدُّنيا كَأنَّكَ غَريبٌ أو عابِرُ سَبيلٍ. وكان ابنُ عُمَرَ يقولُ: إذا أمسَيتَ فلا تَنتَظِرِ الصَّباحَ، وإذا أصبَحتَ فلا تَنتَظِرِ المَساءَ، وخُذ مِن صِحَّتِكَ لمَرَضِكَ، ومِن حَياتِكَ لمَوتِكَ.", "rawi": "عبدالله بن عمر", "book": "صحيح البخاري", "ref": "6416", "grade": "[صحيح]", "takhrij": "من أفراد البخاري على مسلم", "categories": [{"id": "5585a3601c020f9566a200987f170e74", "name": "رقائق وزهد - ما ينبغي لكل مسلم أن يستعمله من قصر الأمل والاستعداد للموت"}, {"id": "28ce07e644cbb25bd29d5ccd5a5840c8", "name": "رقائق وزهد - الزهد في الدنيا"}, {"id": "dd0d0c3a5d234c7725a0e0a05db48f93", "name": "رقائق وزهد - ذكر الموت"}, {"id": "3b314bd99d", "name": "إحسان - الحث على الأعمال الصالحة"}, {"id": "64d0a5baa4", "name": "جنائز وموت - لقاء الله والمبادرة بالعمل الصالح"}]}]$j$::jsonb,
