  ('i-cannot-afford-to-be-generous', 'على كل مسلم صدقة قالوا فإن لم يجد', '2026-08-21T12:00:00Z', $j$[{"id": "Ee2PC71D", "text": "على كُلِّ مُسلِمٍ صَدَقةٌ، فقالوا: يا نَبيَّ اللهِ، فمَن لم يَجِدْ؟ قال: يَعمَلُ بيَدِه، فيَنفَعُ نَفسَه ويَتَصَدَّقُ، قالوا: فإن لم يَجِدْ؟ قال: يُعينُ ذا الحاجةِ المَلهوفَ، قالوا: فإن لم يَجِدْ؟ قال: فليَعمَلْ بالمَعروفِ، وليُمسِكْ عَنِ الشَّرِّ؛ فإنَّها له صَدَقةٌ.", "rawi": "أبو موسى الأشعري", "book": "صحيح البخاري", "ref": "1445", "grade": "[صحيح]", "takhrij": "أخرجه البخاري (1445)، ومسلم (1008)", "categories": [{"id": "5561daf11399bb20365244e5a97002ef", "name": "رقائق وزهد - ما جاء في السعي لقضاء حوائج الخلق"}, {"id": "e1fc46c7103e1504a789cbbfb6bcc942", "name": "صدقة - على كل مسلم صدقة"}, {"id": "573d479b139933cf75f7c7c036120105", "name": "صدقة - فضل الصدقة والحث عليها"}, {"id": "637e20f35c", "name": "صدقة - الحث على المعروف وإعانة الملهوف وإغاثته"}, {"id": "24c06033df", "name": "صدقة - الصدقة ليست مختصة بالإعطاء"}]}]$j$::jsonb,
