  ('i-avoid-someone-i-wronged', 'من كانت له مظلمة لأخيه من عرضه أو شيء فليتحلله منه اليوم', '2026-08-21T12:00:00Z', $j$[{"id": "zQ6nVa8Y", "text": "مَن كانَت له مَظلِمةٌ لأخيه مِن عِرضِه أو شيءٍ فليَتَحَلَّلْه منه اليَومَ، قَبلَ أن لا يَكونَ دينارٌ ولا دِرهَمٌ، إن كان له عَمَلٌ صالِحٌ أُخِذَ منه بقدرِ مَظلِمَتِه، وإن لَم تَكُنْ له حَسَناتٌ أُخِذَ مِن سَيِّئاتِ صاحِبِه فحُمِلَ عليه.", "rawi": "أبو هريرة", "book": "صحيح البخاري", "ref": "2449", "grade": "[صحيح]", "takhrij": "أخرجه البخاري (2449)", "categories": [{"id": "5367fbfb369ad6a4b38df947c471d643", "name": "قيامة - الحساب والقصاص"}, {"id": "d310f2a6246604c1b483b1eb64769446", "name": "مظالم - التحلل من الظلم"}, {"id": "4db7a714b3a5d9f45bcc0f8b7228464e", "name": "مظالم - قصاص المظالم"}, {"id": "8f3e73f4c5", "name": "مظالم - التوبة ورد المظالم والحقوق"}, {"id": "1f8310865a", "name": "مظالم - خطورة المظالم"}]}]$j$::jsonb,
